-- Preserve original supplier invoices, OP and payment blocks; derive release and balances.
ALTER TABLE documents DROP CONSTRAINT documents_kind_check;
ALTER TABLE documents ADD CONSTRAINT documents_kind_check CHECK(kind IN('WORK_ORDER_TASK','TICKET','SERVICE_CASE','BUSINESS_PARTNER','APPROVAL','TECHNICAL_OBJECT','SERVICE_CONTRACT','FIELD_VISIT','SERVICE_ORDER','MATERIAL','MATERIAL_REQUIREMENT','REQUISITION','PURCHASE_ORDER','GOODS_RECEIPT','GOODS_ISSUE','SERVICE_REPORT','INVOICE','CANCELLATION','ACCOUNTING','PAYMENT','QUOTATION','SALES_ORDER','CREDIT_NOTE','BILLING_REQUEST','PARTNER_ACCOUNT','COMPANY_BILLING_PROFILE','SUPPLIER_INVOICE','SUPPLIER_INVOICE_REVERSAL','STOCK_TRANSFER','INVENTORY_COUNT','CUSTOMER_RETURN','CUSTOMER_RETURN_RECEIPT','RETURN_CUSTODY','RETURN_INSPECTION','SUPPLIER_PAYMENT'));
CREATE TABLE supplier_payment_controls(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,invoice_id uuid NOT NULL,company_id uuid NOT NULL,status text NOT NULL CHECK(status IN('IN_REVIEW','RELEASED','BLOCKED')),version integer NOT NULL DEFAULT 1,basis jsonb NOT NULL,requested_by uuid NOT NULL,approved_by uuid,updated_by uuid NOT NULL,note text NOT NULL CHECK(length(trim(note)) BETWEEN 15 AND 2000),updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,invoice_id),FOREIGN KEY(tenant_id,invoice_id) REFERENCES supplier_invoices(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES company_codes(tenant_id,id),FOREIGN KEY(tenant_id,requested_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,approved_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by) REFERENCES users(tenant_id,id)
);
CREATE TABLE supplier_payment_control_events(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,control_id uuid NOT NULL,control_version integer NOT NULL,actor_id uuid NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,control_id,control_version),FOREIGN KEY(tenant_id,control_id) REFERENCES supplier_payment_controls(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id)
);
CREATE TRIGGER supplier_control_event_immutable BEFORE UPDATE OR DELETE ON supplier_payment_control_events FOR EACH ROW EXECUTE FUNCTION reject_attachment_mutation();
CREATE FUNCTION supplier_payment_basis(t uuid,inv uuid) RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT jsonb_build_object('invoiceId',i.id,'journalId',i.journal_id,'companyId',i.company_id,'supplierId',i.supplier_id,'accountId',o.account_id,'amount',o.amount,'currency',i.currency,'snapshotHash',encode(sha256(convert_to(i.snapshot::text,'UTF8')),'hex')) FROM supplier_invoices i JOIN supplier_invoice_open_items o ON o.tenant_id=i.tenant_id AND o.invoice_id=i.id WHERE i.tenant_id=t AND i.id=inv AND i.sealed$$;
CREATE FUNCTION supplier_payment_control_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE org uuid;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Zahlungsfreigabehistorie bleibt erhalten';END IF;
 SELECT d.organization_id INTO org FROM supplier_invoices i JOIN documents d ON d.tenant_id=i.tenant_id AND d.id=i.id WHERE i.tenant_id=NEW.tenant_id AND i.id=NEW.invoice_id AND i.company_id=NEW.company_id AND i.sealed;
 PERFORM 1 FROM company_codes WHERE tenant_id=NEW.tenant_id AND id=NEW.company_id FOR UPDATE;
 IF org IS NULL OR NOT EXISTS(SELECT 1 FROM users u JOIN user_organizations uo ON uo.tenant_id=u.tenant_id AND uo.user_id=u.id WHERE u.tenant_id=NEW.tenant_id AND u.id=NEW.updated_by AND u.active AND u.role IN('ADMIN','ACCOUNTANT') AND uo.organization_id=org) THEN RAISE EXCEPTION 'Aktive Finanzberechtigung dieser Rechnungsorganisation erforderlich';END IF;
 IF TG_OP='INSERT' THEN IF NEW.status<>'IN_REVIEW' OR NEW.version<>1 OR NEW.approved_by IS NOT NULL OR NEW.requested_by<>NEW.updated_by THEN RAISE EXCEPTION 'Zahlungsfreigabe beginnt mit eigenem Prüfauftrag';END IF;
 ELSE IF (NEW.id,NEW.tenant_id,NEW.invoice_id,NEW.company_id) IS DISTINCT FROM(OLD.id,OLD.tenant_id,OLD.invoice_id,OLD.company_id) OR NEW.version<>OLD.version+1 OR NOT((OLD.status='BLOCKED' AND NEW.status='IN_REVIEW') OR(OLD.status='IN_REVIEW' AND NEW.status IN('RELEASED','BLOCKED')) OR(OLD.status='RELEASED' AND NEW.status='BLOCKED')) THEN RAISE EXCEPTION 'Zulässigen versionierten Zahlungsfreigabeübergang verwenden';END IF;
 IF NEW.status<>'IN_REVIEW' AND (NEW.requested_by,NEW.basis) IS DISTINCT FROM(OLD.requested_by,OLD.basis) THEN RAISE EXCEPTION 'Ursprünglicher Zahlungsfreigabe-Prüfstand bleibt erhalten';END IF;END IF;
 IF NEW.status IN('IN_REVIEW','RELEASED') AND (NOT supplier_invoice_effective(NEW.tenant_id,NEW.invoice_id) OR NEW.basis IS DISTINCT FROM supplier_payment_basis(NEW.tenant_id,NEW.invoice_id)) THEN RAISE EXCEPTION 'Unveränderte wirksame Originalrechnung erforderlich';END IF;
 IF NEW.status='IN_REVIEW' AND (NEW.approved_by IS NOT NULL OR NEW.requested_by<>NEW.updated_by) THEN RAISE EXCEPTION 'Prüfauftrag benötigt aktuelle Vorbereitung ohne Eigenfreigabe';END IF;
 IF NEW.status='RELEASED' AND (NEW.approved_by IS NULL OR NEW.approved_by=NEW.requested_by OR NEW.approved_by<>NEW.updated_by) THEN RAISE EXCEPTION 'Zahlungssperre nur durch andere Finanzperson freigeben';END IF;
 RETURN NEW;END;$$;
CREATE TRIGGER supplier_payment_control_guard BEFORE INSERT OR UPDATE OR DELETE ON supplier_payment_controls FOR EACH ROW EXECUTE FUNCTION supplier_payment_control_guard();
CREATE FUNCTION supplier_payment_control_consistent() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE h supplier_payment_controls;BEGIN
 IF TG_TABLE_NAME='supplier_payment_control_events' THEN SELECT * INTO h FROM supplier_payment_controls WHERE tenant_id=NEW.tenant_id AND id=NEW.control_id;ELSE h=NEW;END IF;
 IF NOT EXISTS(SELECT 1 FROM supplier_payment_control_events e WHERE e.tenant_id=h.tenant_id AND e.control_id=h.id AND e.control_version=h.version AND e.actor_id=h.updated_by AND e.snapshot=to_jsonb(h)) THEN RAISE EXCEPTION 'Unveränderlicher Zahlungsfreigabenachweis fehlt';END IF;RETURN NULL;END;$$;
CREATE CONSTRAINT TRIGGER supplier_payment_control_consistent AFTER INSERT OR UPDATE ON supplier_payment_controls DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION supplier_payment_control_consistent();
CREATE CONSTRAINT TRIGGER supplier_payment_control_event_consistent AFTER INSERT ON supplier_payment_control_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION supplier_payment_control_consistent();
CREATE TABLE supplier_settlements(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,invoice_id uuid NOT NULL,company_id uuid NOT NULL,period_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('PAYMENT','REVERSAL')),original_id uuid,bank_account_id uuid NOT NULL,amount numeric(20,2) NOT NULL CHECK(amount>0),currency text NOT NULL,posting_date date NOT NULL,document_date date NOT NULL,reference text NOT NULL CHECK(length(trim(reference)) BETWEEN 3 AND 140),reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 15 AND 2000),prepared_by uuid NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','APPROVED','POSTED','CANCELLED')),version integer NOT NULL DEFAULT 1 CHECK(version>0),reviewed_by uuid,reviewed_at timestamptz,review_note text,journal_id uuid,sealed boolean NOT NULL DEFAULT false,posted_at timestamptz,
 CHECK((kind='REVERSAL')=(original_id IS NOT NULL)),CHECK((status='POSTED')=sealed),CHECK(NOT sealed OR(journal_id IS NOT NULL AND reviewed_by IS NOT NULL AND posted_at IS NOT NULL)),UNIQUE(tenant_id,id),UNIQUE(tenant_id,journal_id),
 FOREIGN KEY(tenant_id,id) REFERENCES documents(tenant_id,id),FOREIGN KEY(tenant_id,invoice_id) REFERENCES supplier_invoices(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES company_codes(tenant_id,id),FOREIGN KEY(tenant_id,period_id) REFERENCES fiscal_periods(tenant_id,id),FOREIGN KEY(tenant_id,bank_account_id) REFERENCES gl_accounts(tenant_id,id),FOREIGN KEY(tenant_id,prepared_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,reviewed_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,journal_id) REFERENCES journals(tenant_id,id),FOREIGN KEY(tenant_id,original_id) REFERENCES supplier_settlements(tenant_id,id)
);
CREATE UNIQUE INDEX supplier_settlement_reversal_once ON supplier_settlements(tenant_id,original_id) WHERE kind='REVERSAL' AND status<>'CANCELLED';
CREATE INDEX supplier_settlement_invoice_posting ON supplier_settlements(tenant_id,invoice_id,posting_date) WHERE sealed;
CREATE TABLE supplier_settlement_reviews(tenant_id uuid NOT NULL,settlement_id uuid NOT NULL,actor_id uuid NOT NULL,reviewed_at timestamptz NOT NULL,prepared_hash text NOT NULL,note text NOT NULL CHECK(length(trim(note)) BETWEEN 15 AND 2000),PRIMARY KEY(tenant_id,settlement_id),FOREIGN KEY(tenant_id,settlement_id) REFERENCES supplier_settlements(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id));
CREATE TRIGGER supplier_settlement_review_immutable BEFORE UPDATE OR DELETE ON supplier_settlement_reviews FOR EACH ROW EXECUTE FUNCTION reject_attachment_mutation();
CREATE FUNCTION supplier_settlement_prepared(h supplier_settlements) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$SELECT to_jsonb(h)-ARRAY['status','version','reviewed_by','reviewed_at','review_note','journal_id','sealed','posted_at']$$;
CREATE FUNCTION supplier_invoice_balance_at(t uuid,inv uuid,day date,exclude_id uuid DEFAULT NULL) RETURNS numeric LANGUAGE sql STABLE AS $$
 SELECT ((CASE WHEN EXISTS(SELECT 1 FROM supplier_invoice_reversals r WHERE r.tenant_id=i.tenant_id AND r.invoice_id=i.id AND r.sealed AND r.posting_date<=day) THEN 0 ELSE o.amount END)-coalesce((SELECT sum(CASE s.kind WHEN 'PAYMENT' THEN s.amount ELSE -s.amount END) FROM supplier_settlements s WHERE s.tenant_id=t AND s.invoice_id=inv AND s.sealed AND s.posting_date<=day AND s.id IS DISTINCT FROM exclude_id),0))::numeric(20,2) FROM supplier_invoice_open_items o JOIN supplier_invoices i ON i.tenant_id=o.tenant_id AND i.id=o.invoice_id WHERE o.tenant_id=t AND o.invoice_id=inv AND i.sealed AND i.posting_date<=day
$$;
CREATE OR REPLACE VIEW supplier_invoice_balances WITH(security_invoker=true) AS
 SELECT o.invoice_id,o.tenant_id,o.company_id,o.supplier_id,o.account_id,o.due_date,o.currency,o.amount,coalesce(c.status<>'RELEASED',true) AS payment_block,supplier_invoice_balance_at(o.tenant_id,o.invoice_id,'9999-12-31')::numeric(20,2) AS balance,r.id AS reversal_id,r.posted_at AS reversed_at,o.payment_block AS original_payment_block,coalesce(c.version,0) AS payment_control_version,coalesce(c.status,'BLOCKED') AS payment_control_status
 FROM supplier_invoice_open_items o LEFT JOIN supplier_invoice_reversals r ON r.tenant_id=o.tenant_id AND r.invoice_id=o.invoice_id AND r.sealed LEFT JOIN supplier_payment_controls c ON c.tenant_id=o.tenant_id AND c.invoice_id=o.invoice_id;
CREATE FUNCTION supplier_settlement_guard() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF TG_OP='DELETE' OR OLD.sealed OR OLD.status='CANCELLED' THEN RAISE EXCEPTION 'Lieferantenzahlung und Historie sind unveränderlich';END IF;
 IF supplier_settlement_prepared(OLD) IS DISTINCT FROM supplier_settlement_prepared(NEW) OR NEW.version<>OLD.version+1 OR NOT((OLD.status='DRAFT' AND NEW.status IN('APPROVED','CANCELLED')) OR(OLD.status='APPROVED' AND NEW.status IN('POSTED','CANCELLED'))) THEN RAISE EXCEPTION 'Zahlungsprüfstand bleibt unverändert; zulässigen Folgestatus verwenden';END IF;
 IF OLD.status='APPROVED' AND (OLD.reviewed_by,OLD.reviewed_at,OLD.review_note) IS DISTINCT FROM(NEW.reviewed_by,NEW.reviewed_at,NEW.review_note) THEN RAISE EXCEPTION 'Unabhängige Zahlungsprüfung bleibt unverändert';END IF;RETURN NEW;END;$$;
CREATE TRIGGER supplier_settlement_frozen BEFORE UPDATE OR DELETE ON supplier_settlements FOR EACH ROW EXECUTE FUNCTION supplier_settlement_guard();
CREATE FUNCTION validate_supplier_settlement() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE h supplier_settlements;i supplier_invoices;o supplier_invoice_open_items;d documents;orig supplier_settlements;j journals;expected jsonb;actual jsonb;b numeric;
BEGIN
 IF TG_TABLE_NAME='journals' THEN SELECT * INTO h FROM supplier_settlements WHERE tenant_id=NEW.tenant_id AND id=NEW.source_id;
  IF h.id IS NULL THEN IF EXISTS(SELECT 1 FROM supplier_settlements s WHERE s.tenant_id=NEW.tenant_id AND s.journal_id=NEW.reversal_of AND s.sealed) THEN RAISE EXCEPTION 'Lieferantenzahlungs-FI nur durch geprüften Zahlungsstorno gegenbuchen';END IF;RETURN NULL;END IF;
 ELSIF TG_TABLE_NAME='supplier_settlement_reviews' THEN SELECT * INTO h FROM supplier_settlements WHERE tenant_id=NEW.tenant_id AND id=NEW.settlement_id;
 ELSE SELECT * INTO h FROM supplier_settlements WHERE tenant_id=NEW.tenant_id AND id=NEW.id;END IF;
 PERFORM 1 FROM company_codes WHERE tenant_id=h.tenant_id AND id=h.company_id FOR UPDATE;
 SELECT * INTO i FROM supplier_invoices WHERE tenant_id=h.tenant_id AND id=h.invoice_id FOR UPDATE;SELECT * INTO o FROM supplier_invoice_open_items WHERE tenant_id=h.tenant_id AND invoice_id=h.invoice_id;SELECT * INTO d FROM documents WHERE tenant_id=h.tenant_id AND id=h.id;
 IF i.id IS NULL OR NOT i.sealed OR o.invoice_id IS NULL OR h.company_id<>i.company_id OR h.currency<>i.currency OR d.kind<>'SUPPLIER_PAYMENT' OR d.organization_id<>(SELECT organization_id FROM documents WHERE tenant_id=i.tenant_id AND id=i.id) OR d.created_by<>h.prepared_by THEN RAISE EXCEPTION 'Gebuchte Lieferantenrechnung und passende Zahlungsidentität erforderlich';END IF;
 IF h.status='CANCELLED' THEN IF h.journal_id IS NOT NULL OR h.sealed THEN RAISE EXCEPTION 'Nur ungebuchten Zahlungsprüfstand verwerfen';END IF;RETURN NULL;END IF;
 IF h.kind='REVERSAL' THEN SELECT * INTO orig FROM supplier_settlements WHERE tenant_id=h.tenant_id AND id=h.original_id;
  IF orig.id IS NULL OR NOT orig.sealed OR orig.kind<>'PAYMENT' OR (h.invoice_id,h.company_id,h.bank_account_id,h.currency,h.amount) IS DISTINCT FROM(orig.invoice_id,orig.company_id,orig.bank_account_id,orig.currency,orig.amount) OR h.posting_date<orig.posting_date THEN RAISE EXCEPTION 'Zahlungsstorno benötigt unveränderten gebuchten Originalbetrag und Konten';END IF;
 ELSE IF NOT supplier_invoice_effective(h.tenant_id,h.invoice_id) OR NOT EXISTS(SELECT 1 FROM supplier_payment_controls c WHERE c.tenant_id=h.tenant_id AND c.invoice_id=h.invoice_id AND c.status='RELEASED' AND c.approved_by<>c.requested_by AND c.basis=supplier_payment_basis(h.tenant_id,h.invoice_id)) THEN RAISE EXCEPTION 'Wirksame Rechnung und unabhängige Freigabe ihrer Zahlungssperre erforderlich';END IF;
 END IF;
 IF h.status IN('APPROVED','POSTED') AND NOT EXISTS(SELECT 1 FROM supplier_settlement_reviews r JOIN users u ON u.tenant_id=r.tenant_id AND u.id=r.actor_id WHERE r.tenant_id=h.tenant_id AND r.settlement_id=h.id AND r.actor_id=h.reviewed_by AND r.actor_id<>h.prepared_by AND r.reviewed_at=h.reviewed_at AND r.note=h.review_note AND r.prepared_hash=encode(sha256(convert_to(supplier_settlement_prepared(h)::text,'UTF8')),'hex') AND u.active AND u.role IN('ADMIN','ACCOUNTANT') AND EXISTS(SELECT 1 FROM user_organizations uo WHERE uo.tenant_id=u.tenant_id AND uo.user_id=u.id AND uo.organization_id=d.organization_id)) THEN RAISE EXCEPTION 'Unabhängige Finanzprüfung des Lieferantenzahlungs-Prüfstands fehlt';END IF;
 IF NOT h.sealed THEN IF h.journal_id IS NOT NULL OR EXISTS(SELECT 1 FROM journals WHERE tenant_id=h.tenant_id AND source_id=h.id) THEN RAISE EXCEPTION 'Zahlungs-FI benötigt vollständig gebuchten Zahlungsbeleg';END IF;RETURN NULL;END IF;
 IF h.posting_date<i.posting_date OR h.document_date<i.invoice_date OR h.posting_date>(now() AT TIME ZONE 'Europe/Berlin')::date OR h.document_date>(now() AT TIME ZONE 'Europe/Berlin')::date OR NOT EXISTS(SELECT 1 FROM fiscal_periods p WHERE p.tenant_id=h.tenant_id AND p.id=h.period_id AND p.company_id=h.company_id AND p.status='OPEN' AND h.posting_date BETWEEN p.date_from AND p.date_to) THEN RAISE EXCEPTION 'Zulässiges Zahlungsdatum und offene passende Periode erforderlich';END IF;
 IF EXISTS(SELECT 1 FROM supplier_settlements s WHERE s.tenant_id=h.tenant_id AND s.invoice_id=h.invoice_id AND s.sealed AND s.id<>h.id AND s.posting_date>h.posting_date) THEN RAISE EXCEPTION 'Zahlung nicht vor bereits gebuchte Zahlungsbewegungen zurückdatieren';END IF;
 IF NOT EXISTS(SELECT 1 FROM gl_accounts a WHERE a.tenant_id=h.tenant_id AND a.id=h.bank_account_id AND a.company_id=h.company_id AND a.active AND a.kind='BANK') OR NOT EXISTS(SELECT 1 FROM gl_accounts a WHERE a.tenant_id=h.tenant_id AND a.id=o.account_id AND a.company_id=h.company_id AND a.active AND a.kind='PAYABLE') THEN RAISE EXCEPTION 'Aktives Bankkonto und ursprüngliches Verbindlichkeitskonto erforderlich';END IF;
 IF h.kind='PAYMENT' THEN
  IF NOT EXISTS(SELECT 1 FROM partner_company_accounts a JOIN business_partners p ON p.tenant_id=a.tenant_id AND p.id=a.partner_id WHERE a.tenant_id=h.tenant_id AND a.company_id=h.company_id AND a.partner_id=i.supplier_id AND a.kind='CREDITOR' AND a.status='ACTIVE' AND NOT a.payment_block AND NOT a.invoice_block AND p.status='ACTIVE') THEN RAISE EXCEPTION 'Aktiver freigegebener Kreditor ohne Stammdaten-Zahlungssperre erforderlich';END IF;
  b=supplier_invoice_balance_at(h.tenant_id,h.invoice_id,h.posting_date,h.id);IF h.amount>b OR h.amount>supplier_invoice_balance_at(h.tenant_id,h.invoice_id,'9999-12-31',h.id) THEN RAISE EXCEPTION 'Lieferantenzahlung übersteigt tatsächlichen datierten oder aktuellen OP-Rest';END IF;
 END IF;
 SELECT * INTO j FROM journals WHERE tenant_id=h.tenant_id AND id=h.journal_id;
 IF j.id IS NULL OR j.status<>'POSTED' OR j.source_id IS DISTINCT FROM h.id OR j.company_id<>h.company_id OR j.period_id<>h.period_id OR j.posting_date<>h.posting_date OR j.document_date<>h.document_date OR j.currency<>h.currency OR j.reversal_of IS DISTINCT FROM orig.journal_id THEN RAISE EXCEPTION 'Passende gebuchte Lieferantenzahlungs-FI fehlt';END IF;
 IF h.kind='REVERSAL' THEN SELECT jsonb_agg(jsonb_build_array(account_id,CASE side WHEN 'DEBIT' THEN 'CREDIT' ELSE 'DEBIT' END,amount,cost_center,partner_id,tax_code,description) ORDER BY position) INTO expected FROM journal_entries WHERE tenant_id=h.tenant_id AND journal_id=orig.journal_id;
 ELSE expected=jsonb_build_array(jsonb_build_array(h.bank_account_id,'CREDIT',h.amount,NULL,NULL,NULL,h.reference),jsonb_build_array(o.account_id,'DEBIT',h.amount,NULL,o.supplier_id,NULL,h.reference));END IF;
 SELECT jsonb_agg(jsonb_build_array(account_id,side,amount,cost_center,partner_id,tax_code,description) ORDER BY position) INTO actual FROM journal_entries WHERE tenant_id=h.tenant_id AND journal_id=j.id;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Zahlung ausschließlich Bank und ursprünglichen Kreditor gegenbuchen';END IF;RETURN NULL;
END;$$;
CREATE CONSTRAINT TRIGGER supplier_settlement_commit_check AFTER INSERT OR UPDATE ON supplier_settlements DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_supplier_settlement();
CREATE CONSTRAINT TRIGGER supplier_settlement_review_check AFTER INSERT ON supplier_settlement_reviews DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_supplier_settlement();
CREATE CONSTRAINT TRIGGER supplier_settlement_journal_check AFTER INSERT OR UPDATE ON journals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_supplier_settlement();
CREATE FUNCTION supplier_reversal_requires_unpaid() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF NEW.sealed AND (EXISTS(SELECT 1 FROM supplier_settlements s WHERE s.tenant_id=NEW.tenant_id AND s.invoice_id=NEW.invoice_id AND s.sealed AND s.posting_date>NEW.posting_date) OR coalesce((SELECT sum(CASE kind WHEN 'PAYMENT' THEN amount ELSE -amount END) FROM supplier_settlements WHERE tenant_id=NEW.tenant_id AND invoice_id=NEW.invoice_id AND sealed),0)<>0) THEN RAISE EXCEPTION 'Vor Rechnungsstorno alle tatsächlichen Zahlungen exakt gegenbuchen und Datumsfolge erhalten';END IF;RETURN NULL;END;$$;
CREATE CONSTRAINT TRIGGER supplier_reversal_requires_unpaid AFTER INSERT OR UPDATE ON supplier_invoice_reversals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION supplier_reversal_requires_unpaid();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['supplier_payment_controls','supplier_payment_control_events','supplier_settlements','supplier_settlement_reviews'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t);END LOOP;END;$$;
